// Catalog URLs are stable across search, paging and cross-links.
const catalogParams=()=>new URLSearchParams((location.hash||'').split('?')[1]||location.search.slice(1));
const catalogHref=(values={})=>'/clinical-library?'+new URLSearchParams(values).toString();
const externalReference=(entry)=>{
 const re=/(https:\/\/[^\s<>"']+)/g;
 return String(entry).split(re).map(part=>{
  if(!part.startsWith('https://'))return esc(part);
  const url=part.replace(/[),.;]+$/,'');
  try{const parsed=new URL(url);if(parsed.protocol!=='https:')return esc(part);return `<a href="${attr(url)}" target="_blank" rel="noopener noreferrer" class="reference-url">${esc(url)}</a>${esc(part.slice(url.length))}`;}catch{return esc(part);}
 }).join('');
};
export async function catalogPage(path){
 const params=catalogParams(),query=params.get('q')||'',kind=params.get('type')||'',page=Math.max(1,Math.min(100000,Number(params.get('page'))||1));
 const perPage=50;
 const response=await err(()=>api.get('/api/v1/clinical-catalog/search?q='+encodeURIComponent(query)+'&type='+encodeURIComponent(kind)+'&page='+page+'&per_page='+perPage));
 const total=response.data?.total||0, pages=Math.max(1,Math.ceil(total/perPage));
 const linked=d=>row(d.title,d.description||d.code||'',catalogHref({q:query,type:kind,page,item:d.kind+':'+d.id}));
 const pager=total>perPage?`<nav aria-label="Страницы справочника" class="row space-between space-top-20"><span class="small muted">Страница ${page} из ${pages} · показаны ${response.data.items.length} из ${total}</span><div class="row">${page>1?link(catalogHref({q:query,type:kind,page:page-1}),'Предыдущая'):''}${page<pages?link(catalogHref({q:query,type:kind,page:page+1}),'Следующая'):''}</div></nav>`:'';
 return `${title('Клинический справочник','Полный каталог диагнозов, препаратов, методов терапии и опросников. Сведения требуют проверки по актуальным источникам.')}${card(`<form class="search-tools" data-form="catalog-search"><div class="field grow"><label for="catalog-q">Поиск</label><input id="catalog-q" class="search-field" type="search" name="q" value="${attr(query)}" placeholder="Препарат, диагноз, метод или опросник"></div><div class="field"><label for="catalog-type">Раздел</label><select id="catalog-type" name="type"><option value="">Все категории</option>${[['diagnosis','Диагнозы'],['medicine','Лекарства'],['therapy','Терапия'],['instrument','Опросники']].map(([v,l])=>`<option value="${v}" ${kind===v?'selected':''}>${l}</option>`).join('')}</select></div><button class="btn btn-primary align-self-end">${icon('search')} Искать</button></form><p class="small muted">${response.error?'Не удалось обновить поиск':`Найдено: ${esc(total)} · Версия: ${esc(response.data.source_version)}`}</p>${params.has('item')?'<div id="catalog-detail" class="space-top-20" aria-live="polite"></div>':''}${response.error?errorState(response.error):list(response.data.items,linked,'Совпадений нет','Попробуйте изменить запрос.')} ${pager}`)}`;
}
export async function catalogDetail(kind,id){
 const r=await err(()=>api.get('/api/v1/clinical-catalog/'+segment(kind)+'/'+segment(id)));
 if(r.error)return protectedError(r.error);
 const d=r.data;
 const referenceSections=safeArray(d.reference_sections).map((section,i)=>({section,i,priority:/доз|способ примен|режим приём|dosage|administration/i.test(section.title||'')})).sort((a,b)=>Number(b.priority)-Number(a.priority));
 const sections=referenceSections.map(({section,i,priority})=>`<section class="reference-section ${priority?'reference-dosing':''}"><h3>${priority?icon('clipboard',18):''}${esc(section.title)}</h3>${priority?'<p class="small muted">Справочная информация. Индивидуальный режим определяет врач.</p>':''}${safeArray(section.items).map(v=>`<p class="reference-line">${externalReference(v)}</p>`).join('')}</section>`).join('');
 const links=safeArray(d.links).length?`<div class="reference-section"><h3>Связанные материалы</h3>${safeArray(d.links).map(l=>row(l.title,({diagnosis:'Диагноз',medicine:'Препарат',therapy:'Метод терапии',instrument:'Опросник'})[l.kind]||l.kind,catalogHref({item:l.kind+':'+l.id}))).join('')}</div>`:'';
 const actions=d.kind==='instrument'&&['phq_9','phq_2','gad_7','gad_2'].includes(d.id)?`<div class="row">${link('/assessments/'+segment(d.id),'Пройти выбранный опросник','primary')}</div>`:'';
 const close=link(catalogHref({q:catalogParams().get('q')||'',type:catalogParams().get('type')||'',page:catalogParams().get('page')||1}),'Закрыть карточку');
 return card(`<div class="row space-between"><div><p class="eyebrow">${esc(d.kind||'Справочник')} · ${esc(d.source_version||'')}</p><h2>${esc(d.title)}</h2><p class="muted">${esc(d.code||d.id||'')}</p></div><span class="pill">Справочный материал</span></div>${d.reference_warning?notice(d.reference_warning,true):''}${d.license_note?notice(d.license_note,true):''}<p>${esc(d.description||'')}</p>${actions}${sections}${links}<div class="space-top-20">${close}</div>`);
}
